  "Conductor Mix": "導體混合",
  "Confirm · {balance}→{result}D": "確認·{balance}→{result}D",
  "Confirm · {before}→{after}": "確認·{before}→{after}",
  "Confirm {action}. Spend {cost} Diamonds. Balance {before} to {after}.": "確認 {action}。花費 {cost} 鑽石。平衡 {before} 到 {after}。",
